`<div class="food-content-body" data-food-date="${requestedDate}">
    <section class="nutrition-hero food-nutrition-hero" data-food-date="${requestedDate}" aria-label="${isToday ? '今日' : '当日'}营养汇总"><div class="nutrition-hero-head"><span class="hero-label">饮食总览</span><button class="text-btn" data-edit-nutrition-target>${target ? '编辑目标' : '设置目标'} ${icon('chevron', 16)}</button></div><div class="food-calorie-row">${calorieGaugeHtml(totals.calories, calorieTarget, 'food', previous.get('calories'))}</div><div class="macros" data-macro-summary-host>${macroNutritionSummaryForDay(nutrition)}</div>${target?.strategySelection ? `<p class="strategy-food-source">${esc(target.strategySelection.templateName)} · ${esc(target.strategySelection.variantName)}</p>` : target?.cycleSelection?`<p class="strategy-food-source">${esc(target.cycleSelection.cycleName)} · ${esc(target.cycleSelection.variantName)}</p>`:''}</section>
    ${completionStrip}

    ${scheduled?`<section class="food-cycle-plan"><strong>${esc(scheduled.cycle.name)} · 当日安排</strong><span>${esc(scheduled.day.nutrition?.variantName??'未指定营养目标')} · ${esc(scheduled.day.dietTemplate?.name??'无饮食模板')}</span><p>仅为安排，未计入实际摄入。</p><div>${scheduled.day.nutrition?'<button type="button" class="text-btn" data-food-cycle-target>预览 / 应用目标</button>':''}${scheduled.day.dietTemplate?'<button type="button" class="text-btn" data-food-cycle-diet>预览饮食模板</button>':''}</div></section>`:''}
    <section class="food-meals-head"><div><h2>${isToday ? '今日' : '当日'}饮食</h2><span>${logs.length ? `${logs.length} 项记录` : '按餐次记录，更清楚'}</span></div>${logs.length ? '<button class="food-save-template" id="save-day-diet-template" type="button" aria-label="将当天饮食保存为模板">保存为模板</button>' : ''}</section>
    <div class="food-meals">${groups.map((group) => foodMealSectionHtml(group, isToday, expandedMeals.has(group.meal ?? 'unclassified'))).join('')}</div>${dietEventEntryHtml(dietEvents, esc)}</div>`

`<div class="cardio-history">${sessions.length ? sessions.map((session) => {
    const label = getCardioActivityLabel(session)
    const metrics = formatCardioMetrics(session).join(' · ')
    return `<button data-history-cardio="${session.id}" aria-label="编辑 ${formatShortDate(session.date)} ${label}，${formatNumber(session.durationMinutes)} 分钟${metrics ? `，${metrics}` : ''}"><span class="cardio-history-row"><span><strong>${formatShortDate(session.date)}</strong><small>${label}${session.note ? ' · 有日志' : ''}</small></span><span class="cardio-history-value"><strong>${formatNumber(session.durationMinutes)} <small>分钟</small></strong><small>${metrics}</small></span></span></button>`
  }).join('') : '<div class="cardio-history-empty"><strong>还没有有氧训练记录</strong><p>记录楼梯机或跑步机的训练</p><button class="primary" id="history-add-cardio">记录训练</button></div>'}</div>`

`<div role="row">${days.slice(row * 7, row * 7 + 7).map(day => {
    const label = new Intl.DateTimeFormat('zh-CN', { year: 'numeric', month: 'long', day: 'numeric', weekday: 'long' }).format(new Date(`${day.date}T12:00:00`))
    return `<button type="button" role="gridcell" class="date-picker-day${day.isCurrentMonth ? '' : ' outside-month'}" data-date="${day.date}" tabindex="${day.date === state.focused ? 0 : -1}" aria-selected="${day.date === state.selected}" ${day.date === state.today ? 'aria-current="date"' : ''} aria-label="${label}${day.date === state.today ? '，今天' : ''}${day.date === state.selected ? '，已选中' : ''}"><span>${day.day}</span></button>`
  }).join('')}</div>`

`<div class="remaining-goals-grid ${compact ? 'goal-mini-grid' : 'gap-grid'}">${completionKeys.map(key => {
    const text = completionGapText(summary, key)
    const above = !summary.uncertainKeys.includes(key) && (summary.gap[key] ?? 0) < 0
    const value = compact ? text.replace(/^还差 /, '差 ').replace(/^已超 /, '超 ').replace('已达目标', '已达标') : text
    const label = compact ? `<span class="goal-mini-label"><i aria-hidden="true" class="goal-mini-dot ${key}"></i>${completionLabels[key]}</span>` : `<small>${completionLabels[key]}</small>`
    return `<div class="remaining-goal ${key} ${compact ? 'goal-mini-item' : 'gap-item'}${above ? ' is-above' : ''}" data-gap-text="${text}">${label}<strong title="${text}" aria-label="${completionLabels[key]}：${text}">${value}</strong></div>`
  }).join('')}</div>`
